def read64(s:readbuf, at:u64) -> u64:
    value = 0
    index = 0
    while index < 8:
        value = value | (byte(s, at + index) << (index * 8))
        index = index + 1
    return value

def read32(s:readbuf, at:u64) -> u64:
    value = 0
    index = 0
    while index < 4:
        value = value | (byte(s, at + index) << (index * 8))
        index = index + 1
    return value

def get(w:mutbuf, at:u64) -> u64:
    value = 0
    index = 0
    while index < 8:
        value = value | (byte(w, at + index) << (index * 8))
        index = index + 1
    return value

def get32(w:mutbuf, at:u64) -> u64:
    value = 0
    index = 0
    while index < 4:
        value = value | (byte(w, at + index) << (index * 8))
        index = index + 1
    return value

