        return False
    index = 0
    while index < size:
        if read32(s, begin + index * 4) != byte(w, get(w, at) + index):
            return False
        index = index + 1
    return True

def literal_prefix(s:readbuf, w:mutbuf, begin:u64, size:u64, literal:u64) -> bool:
    at = LITERAL_BASE + literal * 16
    if size > get(w, at + 8):
        return False
    index = 0
    while index < size:
        if read32(s, begin + index * 4) != byte(w, get(w, at) + index):
            return False
        index = index + 1
    return True

