    matches = 0
    token = 0
    while token < TOKEN_COUNT:
        if (allowed & (1 << token)) != 0:
            same = literal_equal(s, w, begin, size, token_literal(token))
            if prefix:
                same = literal_prefix(s, w, begin, size, token_literal(token))
            if same:
                matches = matches | (1 << token)
        token = token + 1
    return matches

